import { useQuery } from '@tanstack/react-query'
import { useEffect, useRef } from 'react'
import { Api } from '../services/endpoints'

const BG = '#fbfdff'
const GRID = '#e8eef6'
const WINDOW_SECONDS = 6

/**
 * Sweeping ECG trace. Samples are generated by the API (Python) and drawn at their real sampling
 * rate; the cursor erases just ahead of itself like a bedside monitor.
 */
export function EcgCanvas({ monitorId, height = 110, color = '#0f7b4f' }: { monitorId: string; height?: number; color?: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const sizedRef = useRef(false)
  const { data } = useQuery({
    queryKey: ['ecg', monitorId],
    queryFn: () => Api.ecg(monitorId, WINDOW_SECONDS),
    refetchInterval: WINDOW_SECONDS * 1000,
    staleTime: 5000,
  })

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || !data) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return
    const width = canvas.clientWidth || 400
    const pxPerSecond = width / WINDOW_SECONDS
    const gridStep = pxPerSecond / 5

    const paintBand = (x0: number, x1: number) => {
      ctx.fillStyle = BG
      ctx.fillRect(x0, 0, x1 - x0, height)
      ctx.strokeStyle = GRID
      ctx.lineWidth = 1
      ctx.beginPath()
      for (let gx = Math.ceil(x0 / gridStep) * gridStep; gx < x1; gx += gridStep) {
        ctx.moveTo(gx + 0.5, 0)
        ctx.lineTo(gx + 0.5, height)
      }
      for (let gy = 0; gy <= height; gy += height / 6) {
        ctx.moveTo(x0, gy + 0.5)
        ctx.lineTo(x1, gy + 0.5)
      }
      ctx.stroke()
    }

    if (!sizedRef.current) {
      const dpr = window.devicePixelRatio || 1
      canvas.width = width * dpr
      canvas.height = height * dpr
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      paintBand(0, width)
      sizedRef.current = true
    }
    const samples = data.samples
    if (!samples.length) {
      paintBand(0, width)
      return
    }
    const fs = data.fs
    const mid = height * 0.62
    const scale = height * 0.42
    const xOf = (i: number) => ((i / fs) % WINDOW_SECONDS) * pxPerSecond
    const yOf = (i: number) => mid - samples[i]! * scale
    const start = performance.now()
    let lastIndex = 0
    let raf = 0

    const frame = (now: number) => {
      const index = Math.min(samples.length - 1, Math.floor(((now - start) / 1000) * fs))
      if (index > lastIndex) {
        const xNow = xOf(index)
        paintBand(xNow + 1, Math.min(width, xNow + 16))
        ctx.strokeStyle = color
        ctx.lineWidth = 2
        ctx.lineJoin = 'round'
        ctx.beginPath()
        let prevX = xOf(lastIndex)
        ctx.moveTo(prevX, yOf(lastIndex))
        for (let i = lastIndex + 1; i <= index; i++) {
          const px = xOf(i)
          if (px < prevX) ctx.moveTo(px, yOf(i))
          else ctx.lineTo(px, yOf(i))
          prevX = px
        }
        ctx.stroke()
        lastIndex = index
      }
      if (index < samples.length - 1) raf = requestAnimationFrame(frame)
    }
    paintBand(0, 16)
    raf = requestAnimationFrame(frame)
    return () => cancelAnimationFrame(raf)
  }, [data, height, color])

  return (
    <div style={{ position: 'relative' }}>
      <canvas ref={canvasRef} className="ecg-canvas" style={{ height }} aria-label={`ECG waveform for ${monitorId}`} role="img" />
      {data && data.status !== 'ok' && <div className="ecg-overlay">{data.status === 'leads_off' ? 'ECG LEADS OFF' : 'NO SIGNAL'}</div>}
    </div>
  )
}
